#include <bits/stdc++.h>
using namespace std;
class Solution {
    using ll=long long;
    static const ll INF=(1LL<<60);
    struct State{ll hi,lo;State(ll h=-INF,ll l=INF):hi(h),lo(l){}};
public:
    int subtreeInversionSum(vector<vector<int>>& edges,vector<int>& a,int k){
        int n=a.size();vector<vector<int>>g(n);
        for(auto&e:edges){g[e[0]].push_back(e[1]);g[e[1]].push_back(e[0]);}
        vector<int>par(n,-1),order(1,0);
        for(int i=0;i<(int)order.size();i++){
            int u=order[i];for(int v:g[u])if(v!=par[u])par[v]=u,order.push_back(v);
        }
        vector<vector<State>>dp(n);
        for(int z=n-1;z>=0;z--){
            int u=order[z];vector<State>cur(k+1);cur[k]=State(a[u],a[u]);
            ll invHi=-a[u],invLo=-a[u];
            for(int v:g[u])if(v!=par[u]){
                vector<State>next(k+1);
                ll childHi=-INF,childLo=INF;
                for(int d=max(0,k-1);d<=k;d++){
                    childHi=max(childHi,dp[v][d].hi);
                    childLo=min(childLo,dp[v][d].lo);
                }
                invHi-=childLo;invLo-=childHi;
                for(int d=0;d<=k;d++)if(cur[d].hi!=-INF){
                    for(int e=0;e<=k;e++)if(dp[v][e].hi!=-INF){
                        int ce=min(k,e+1);
                        if(d+ce<k)continue;
                        int nd=min(d,ce);
                        next[nd].hi=max(next[nd].hi,cur[d].hi+dp[v][e].hi);
                        next[nd].lo=min(next[nd].lo,cur[d].lo+dp[v][e].lo);
                    }
                }
                cur.swap(next);
                vector<State>().swap(dp[v]);
            }
            cur[0].hi=max(cur[0].hi,invHi);
            cur[0].lo=min(cur[0].lo,invLo);
            dp[u].swap(cur);
        }
        ll ans=-INF;for(auto &st:dp[0])ans=max(ans,st.hi);
        return (int)ans;
    }
};
